-- Tác vụ AI để trang admin "Tác vụ AI" có đủ trạng thái: hoàn tất, lỗi, đang chạy, chờ, hủy
INSERT INTO ai_tasks
    (id, member_id, score_id, task_type, status, progress, step, error_message, input_data, retry_count,
     result_data, created_at, updated_at, started_at, finished_at)
SELECT UUID(), m.id, s.id, t.task_type, t.status, t.progress, t.step, t.error_message, t.input_data, t.retry_count,
       t.result_data, t.created_at, t.updated_at, t.started_at, t.finished_at
FROM (
    SELECT 'lan.nguyen@music.com' AS email, 'Für Elise' AS title, 'OMR_CONVERSION' AS task_type, 'COMPLETED' AS status, 100 AS progress, 'EXPORT' AS step, NULL AS error_message, '{"sourceType": "SCAN", "preprocess": true}' AS input_data, 0 AS retry_count, '{"pages": 3, "measureCount": 124}' AS result_data, NOW(6) - INTERVAL 45 DAY - INTERVAL 3 HOUR - INTERVAL 20 MINUTE AS created_at, NOW(6) - INTERVAL 45 DAY - INTERVAL 3 HOUR - INTERVAL 14 MINUTE AS updated_at, NOW(6) - INTERVAL 45 DAY - INTERVAL 3 HOUR - INTERVAL 19 MINUTE AS started_at, NOW(6) - INTERVAL 45 DAY - INTERVAL 3 HOUR - INTERVAL 14 MINUTE AS finished_at
